      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp8(:), tmp10(:), &
                               tmp13(:), tmp14(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), &
                               tmp20(:), tmp21(:), tmp22(:), tmp23(:), tmp24(:), tmp25(:), &
                               tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:), &
                               tmp32(:), tmp33(:), tmp34(:), tmp35(:), tmp36(:), tmp37(:), &
                               tmp38(:), tmp39(:), tmp40(:), tmp42(:), tmp43(:), tmp44(:), &
                               tmp45(:), tmp48(:), tmp49(:), tmp50(:), tmp51(:), tmp52(:), &
                               tmp53(:), tmp54(:)
      real(wp), allocatable :: tmp6(:), tmp7(:), tmp15(:)
      real(wp) :: tmp9, tmp11, tmp12, tmp41, tmp46, tmp47, tmp55, tmp56

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] call nonlocal_pcm_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] vn: wrong shape")
         return
      end if
      if (any(shape(u) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] u: wrong shape")
         return
      end if
