      state%ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s13
      state%op1%c2 => state%s14
      state%op1%c4 => state%s18
      state%op1%c6 => state%s20
      state%v = v
      state%vn = vn
      call gemv(state%s13, state%v, state%s23)
