      tmp6(1:npt) = tmp5
      tmp6(npt + 1:2*npt) = 0.0_wp
      tmp6(2*npt + 1:3*npt) = 0.0_wp
      tmp7 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp6, tmp7, error)
      if (allocated(error)) return
