      state%s30 = tmp7(1:npt)
      tmp8 = state%a*state%s29
      tmp9 = dot(tmp8, state%v)
      tmp10 = state%a*state%s30
      tmp11 = dot(tmp10, state%vn)
      tmp12 = -tmp11
      state%s31 = tmp9 + tmp12
      state%s32 = tmp7(2*npt + 1:3*npt)
      state%s34 = state%s33*state%vn
      state%s35 = state%s2*state%v
      tmp13 = state%s34*state%a
      tmp14 = state%s35*state%a
      tmp15(1:npt) = tmp13
      tmp15(npt + 1:2*npt) = tmp14
      tmp15(2*npt + 1:3*npt) = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp15, state%s36, error)
      if (allocated(error)) return
      state%s37 = state%s36(1:npt)
      state%s38 = state%s22*state%s37
      state%s39 = state%s27*state%s37
      state%s40 = state%s24*state%s37
      state%s43 = state%s36(2*npt + 1:3*npt)
      state%s44 = -state%s43
      state%s45 = -state%s37
      state%s46 = state%s44 + state%s45
