      call gemv(state%s13, state%s38, tmp17, trans="t")
      grad_v = tmp16 + tmp17
      tmp18 = state%s33*tmp10
      call gemv(state%s20, state%s39, tmp19, trans="t")
      tmp20 = tmp18 + tmp19
      call gemv(state%s18, state%s40, tmp21, trans="t")
      grad_vn = tmp20 + tmp21
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp22 = 6.283185307179586_wp*state%s30
         call gemv(state%s13, state%s30, tmp23)
         tmp24 = -tmp23
         tmp25 = tmp22 + tmp24
         call gemv(state%s14, state%s30, tmp26)
         tmp27 = -tmp26
         tmp28 = tmp25 + tmp27
         tmp29 = -tmp28
         tmp30 = tmp5 + tmp29
         call gemv(state%s18, state%s29, tmp31)
         tmp32 = state%s17*tmp31
         call gemv(state%s20, state%s29, tmp33)
         tmp34 = state%s19*tmp33
         tmp35 = tmp32 + tmp34
         tmp36 = -tmp35
         tmp37 = tmp30 + tmp36
         call gemv(state%s13, state%s32, tmp38)
         tmp39 = state%s41*tmp38
         tmp40 = tmp37 + tmp39
         tmp41 = dot(state%s37, tmp40)
         tmp42 = state%s36(npt + 1:2*npt)
         tmp43 = tmp22 + tmp26
         tmp44 = -tmp43
         tmp45 = tmp44 + tmp33
         tmp46 = dot(tmp42, tmp45)
         tmp47 = tmp41 + tmp46
         tmp48 = state%s26*tmp33
